if (!function_exists('getStatusBadge')) {
    function getStatusBadge(string $status): array
    {
        return match ($status) {
            'pending' => ['bg' => 'bg-yellow-500/20', 'text' => 'text-yellow-300', 'label' => 'Menunggu'],
            'paid' => ['bg' => 'bg-blue-500/20', 'text' => 'text-blue-300', 'label' => 'Sudah Bayar'],
            'processing' => ['bg' => 'bg-blue-500/20', 'text' => 'text-blue-300', 'label' => 'Diproses'],
            'shipped' => ['bg' => 'bg-purple-500/20', 'text' => 'text-purple-300', 'label' => 'Dikirim'],
            'completed' => ['bg' => 'bg-green-500/20', 'text' => 'text-green-300', 'label' => 'Selesai'],
            'cancelled' => ['bg' => 'bg-red-500/20', 'text' => 'text-red-300', 'label' => 'Batal'],
            default => ['bg' => 'bg-gray-500/20', 'text' => 'text-gray-300', 'label' => 'Unknown'],
        };
    }
}